describe('Search Term Exclusion by Prefixing with "-"', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should exclude a search term when prefixed with "-" and return relevant results', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform search with exclusion
    cy.get('[data-testid="search-input"]').type('laptop -office');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the search API call
    cy.wait('@searchRequest');

    // Verify results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');

    // Verify results contain "laptop" but not "office"
    cy.get('[data-testid="search-result-item"]').should('contain', 'laptop');
    cy.get('[data-testid="search-result-item"]').should('not.contain', 'office');

    // Verify the exclusion term is correctly processed
    cy.get('[data-testid="search-term-display"]').should('contain', 'laptop');
    cy.get('[data-testid="search-term-display"]').should('contain', '-office');

    // Verify results are returned
    cy.get('[data-testid="result-count"]').should('contain', '1');
  });

  it('should handle multiple excluded terms and return no results when all terms are excluded', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Perform search with multiple exclusions
    cy.get('[data-testid="search-input"]').type('laptop -office -desk');
    cy.get('[data-testid="search-button"]').click();

    // Wait for the search API call
    cy.wait('@searchRequest');

    // Verify no results are displayed
    cy.get('[data-testid="search-results-container"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');

    // Verify the exclusion terms are correctly processed
    cy.get('[data-testid="search-term-display"]').should('contain', 'laptop');
    cy.get('[data-testid="search-term-display"]').should('contain', '-office');
    cy.get('[data-testid="search-term-display"]').should('contain', '-desk');

    // Verify result count is zero
    cy.get('[data-testid="result-count"]').should('contain', '0');
  });
});
